python -c "
import funcy
from datetime import timedelta

# R1
print('R1 has_path:', funcy.has_path({'a': {'b': 1}}, ['a', 'b']))
print('R1 get_in:', funcy.get_in({'a': {'b': 1}}, ['a', 'b']))
print('R1 update_in:', funcy.update_in({'a': {'b': 1}}, ['a', 'b'], lambda x: x+1))
print('R1 zip_dicts:', funcy.zip_dicts(['a', 'b'], [1, 2]))

# R2
@funcy.throttle(5, 1.0)
def t(): return 42
print('R2 throttle:', t())

# R3
@funcy.memoize
def m(x):
    if x < 0: raise funcy.memoize.skip('s')
    return x*2
print('R3 memoize.skip:', m(-1))

@funcy.cache(10)
def c(x):
    if x < 0: raise funcy.cache.skip('s')
    return x*2
print('R3 cache.skip:', c(-1))

# R4
try:
    with funcy.reraise(ValueError, lambda e: TypeError(str(e))):
        raise ValueError('e')
except TypeError as e:
    print('R4 reraise callable:', str(e))

# R5
@funcy.decorator
def d(call, *, kw='x'): return call()
@d(kw='y')
def f(x): return x*2
print('R5 decorator kwonly:', f(5))

# R6
def g(a, b, *, c): return a+b+c
print('R6 autocurry kwargs:', funcy.autocurry(g)(1)(2)(c=3))

# R7
@funcy.throttle(5, timedelta(milliseconds=100))
def h(): return 42
print('R7 throttle timedelta:', h())
"
